<script setup>
import { computed, ref, watch, onBeforeUnmount } from 'vue';
import { Database, Grid2X2, PanelRightClose, PanelRightOpen, Settings2, Maximize2, Play, Pause, ChevronRight, ArrowLeft, Check, Info, Crosshair, Clock3 } from 'lucide-vue-next';
import UiButton from '../../components/ui/UiButton.vue';
import UiSelect from '../../components/ui/UiSelect.vue';
import UiInput from '../../components/ui/UiInput.vue';
import UiDrawer from '../../components/ui/UiDrawer.vue';
import PrototypeChart from './PrototypeChart.vue';
import PrototypeOrder from './PrototypeOrder.vue';
const props = defineProps({ variant: { type: String, default: 'A' }, scene: { type: String, default: 'training' }, feature: { type: String, default: 'hierarchy' }, narrow: Boolean, theme: { type: String, default: 'dark' } });
const emit = defineEmits(['state', 'scene']);
const before = computed(() => props.variant === 'before');
const drawerClass = computed(() => `proto-drawer proto-theme-${props.theme}`);
const sceneNow = ref(props.scene);
const dataOpen = ref(false), settingsOpen = ref(false), layoutOpen = ref(false), orderOpen = ref(false), planOpen = ref(false), detailOpen = ref(false), finishOpen = ref(false), historyOpen = ref(false);
const dataTab = ref('数据池'), dataPool = ref('OKX 历史池'), costOpen = ref(false), tab = ref('持仓'), market = ref('全部'), status = ref('全部状态'), attempt = ref('全部类型'), keyword = ref('');
const layout = ref('dual'), selected = ref(0), periods = ref([before.value?'5m':'1h','5m','15m','4h']), sources = ref(['最新价','最新价','最新价','最新价']);
const crosshair = ref(null), crossSync = ref(true), priceSync = ref(true), timeSync = ref(true), periodSync = ref(false), dateSync = ref(false), zoom = ref(1), offsets = ref([0,0,0,0]), maximized = ref(null);
const clock = ref(45), held = ref(false), orders = ref([]), phase = ref(props.scene==='review'?'completed':'active'), revealed = ref(false), blindSaved = ref(false), reviewSaved = ref(false), margin = ref(500), protection = ref(false), manualPlan = ref(false), planPrice = ref(''), playing = ref(false);
const notice = ref(''), selectedRecord = ref(null);
const orderDraft = ref({});
const currentOrders = computed(() => orders.value.filter(o=>o.status==='pending'));
const displayedOrders = computed(() => tab.value==='当前委托'?currentOrders.value:tab.value==='成交'?orders.value.filter(o=>o.status==='filled'):orders.value);
function orderCount(t) { return t==='持仓'?(held.value?1:0):t==='当前委托'?currentOrders.value.length:t==='成交'?orders.value.filter(o=>o.status==='filled').length:orders.value.length; }
function cancel(order) { order.status='canceled'; notice.value='委托已撤销，历史记录保留（演示）。'; }
const startingCash = ref('10000'), leverage = ref('5'), slippage = ref('2 bps · 默认'), instrument = ref('BTCUSDT 永续');
const preferredUnit = ref('USDT'), confirmClose = ref(true), pauseOnEvent = ref(true), precision = ref('自动 · 按标的');
let playbackTimer;
watch(playing, value => {
  clearInterval(playbackTimer);
  if(value) playbackTimer=setInterval(()=>{ if(phase.value==='active') clock.value+=1; else playing.value=false; },1200);
});
onBeforeUnmount(()=>clearInterval(playbackTimer));
const initialRecords = [
  { id: 'C-014', market: '加密合约', symbol: 'BTCUSDT 永续', status: '进行中', kind: '首次', progress: 'T+45m', result: '—', date: '今天 10:20' },
  { id: 'A-038', market: 'A股', symbol: '匿名场景 A', status: '已完成', kind: '首次', progress: '60 / 60天', result: '+2.18%', date: '昨天 16:30' },
  { id: 'C-013', market: '加密合约', symbol: 'ETHUSDT 永续', status: '待复盘', kind: '首次', progress: '已结束', result: '待揭晓', date: '昨天 14:10' },
  { id: 'C-012', market: '加密合约', symbol: 'BTCUSDT 永续', status: '已完成', kind: '复练', progress: '已结束', result: '+1.36%', date: '10月20日' },
];
const records = ref(initialRecords);
const filtered = computed(() => records.value.filter(r => (market.value==='全部' || r.market===market.value) && (status.value==='全部状态' || r.status===status.value) && (attempt.value==='全部类型' || r.kind===attempt.value) && `${r.id}${r.symbol}`.toLowerCase().includes(keyword.value.toLowerCase())));
const count = computed(() => layout.value==='quad' ? 4 : layout.value==='single' ? 1 : 2);
const visibleCharts = computed(() => maximized.value == null ? Array.from({length:count.value},(_,i)=>i) : [maximized.value]);
const state = computed(() => ({ '页面':sceneNow.value, '方案':props.variant, '图表布局':layout.value, '选中图':selected.value+1, '周期':periods.value, '价格类型':sources.value, '联动':{十字线:crossSync.value,价格:priceSync.value,时间:timeSync.value,周期:periodSync.value,日期范围:dateSync.value}, '查看偏移分钟': offsets.value, '缩放':zoom.value, '训练进度':`T+${clock.value}m`, '练习状态':phase.value, '持仓':held.value, '委托数量':orders.value.length, '手动计划':manualPlan.value, '自动保护':protection.value, '记录筛选':{市场:market.value,状态:status.value,类型:attempt.value}, '已保存盲评':blindSaved.value, '已揭晓':revealed.value, '已保存自评':reviewSaved.value, '开局设置':{合约:instrument.value,资金:startingCash.value,杠杆:leverage.value,滑点:slippage.value}, '设置':{默认单位:preferredUnit.value,平仓确认:confirmClose.value,事件后暂停:pauseOnEvent.value,精度:precision.value}, '弹层':{数据:dataOpen.value,设置:settingsOpen.value,布局:layoutOpen.value,退出计划:planOpen.value,详情:detailOpen.value}, '自动播放':playing.value,'下单草稿':orderDraft.value,'当前委托':currentOrders.value.length }));
watch(state, value => emit('state',value), {deep:true,immediate:true});
function toScene(value) { sceneNow.value=value; }
watch(() => props.scene, value => { playing.value=false; toScene(value); if(value==='review') phase.value='completed'; });
watch(() => props.feature, (f) => {
  dataOpen.value=false; settingsOpen.value=false; orderOpen.value=false; detailOpen.value=false; layoutOpen.value=false; maximized.value=null;
  if (['data','rules'].includes(f) && !before.value) { dataOpen.value=true; dataTab.value=f==='rules'?'训练规则':'数据池'; }
  if (['layout','link','period'].includes(f) && !before.value) { layout.value=f==='layout'?'quad':'dual'; layoutOpen.value=true; }
  if (f==='plan' && !before.value) planOpen.value=true;
}, { immediate: true });
function changePeriod(v) { if(periodSync.value) periods.value=periods.value.map(()=>v); else periods.value[selected.value]=v; }
function pan(delta) { const next=Math.max(0, offsets.value[selected.value]+delta); if(timeSync.value) offsets.value=offsets.value.map(()=>next); else offsets.value[selected.value]=next; }
function advance(n=1) { if(phase.value!=='active') return; clock.value+=n; playing.value=false; notice.value=`已推进到 T+${clock.value}m；所有图共用这一进度。`; }
function submit(order) { if(order.operation==='平仓'&&order.type==='市价') held.value=false; else if(order.type==='市价') held.value=true; orders.value.push({...order,status:order.type==='限价'?'pending':'filled'}); playing.value=false; notice.value=order.type==='限价'?'限价委托已加入“当前委托”（演示）。':'已模拟成交，行情在此暂停。'; tab.value=order.type==='限价'?'当前委托':'持仓'; }
function finish() { phase.value='completed'; finishOpen.value=false; held.value=false; playing.value=false; sceneNow.value='review'; notice.value='已结束本局，先保存盲评，再揭晓。'; records.value[0]={...records.value[0],status:'待复盘',progress:'已结束'}; }
function resume(record=records.value[0]) { selectedRecord.value=record; detailOpen.value=false; historyOpen.value=false; if(record.status==='进行中') { phase.value='active'; sceneNow.value='training'; notice.value='继续原来的进度，不新建一局。'; } else { sceneNow.value='review'; phase.value='completed'; revealed.value=record.status==='已完成'; blindSaved.value=revealed.value; } }
function fresh() { phase.value='active'; sceneNow.value='training'; clock.value=0; held.value=false; orders.value=[]; blindSaved.value=false; revealed.value=false; reviewSaved.value=false; notice.value='已开始一局演示练习。'; }
function reviewAction() { reviewSaved.value=true; records.value[0]={...records.value[0],status:'已完成',result:'+0.00%'}; notice.value='复盘已保存到统一演练记录（内存演示）。'; }
function onHotkey(event) { if(event.key==='Escape') { layoutOpen.value=false; maximized.value=null; } }
</script>
