      <div class="proto-setup-layout">
        <div class="proto-intro">
<span class="proto-eyebrow">观察 → 决策 → 验证</span><h2>用未知行情，<br>练习每一次退出。</h2><p>一次只练一个合约。先形成判断，再让行情检验它。</p><div class="proto-facts"><span>90天背景</span><span>72小时回放</span><span>逐仓 · 单向</span></div>
          <div v-if="before" class="proto-old-data" data-feature="data"><strong>已核对的历史数据池</strong><p>210个场景 / 普通价格 / 标记价格 / 资金费归档</p><div v-for="n in 4" :key="n" class="proto-skeleton" :style="{width:`${95-n*9}%`}"></div><p>数据版本、来源缺口、准入说明与覆盖明细……</p><div class="proto-rule-block"><strong>保守教学结算</strong><p>分钟撮合、容量、强平与资金费的教学说明……</p></div></div>
          <div v-else class="proto-resume" data-feature="resume"><div><span class="proto-status-dot"></span><strong>有一局练习正在等你</strong><p>BTCUSDT · T+45m · 原持仓与委托保留</p></div><UiButton variant="secondary" @click="resume()">继续上次练习 <ChevronRight :size="14" /></UiButton><button type="button" class="proto-text-button" @click="toScene('records')">查看全部演练记录</button></div>
        </div>
        <section class="proto-start-form"><div class="proto-section-title"><h3>这次怎么练？</h3><span>01 / 开始</span></div><label>合约<UiSelect v-model="instrument" aria-label="演示合约"><option>BTCUSDT 永续</option><option>ETHUSDT 永续</option></UiSelect></label><template v-if="before || costOpen"><label>起始资金 · USDT<UiInput v-model="startingCash" aria-label="演示起始资金" /></label><label>杠杆倍数<UiInput v-model="leverage" aria-label="演示杠杆" /></label><label>单边教学滑点<UiSelect v-model="slippage" aria-label="演示滑点"><option>2 bps · 默认</option><option>0 bps · 对照</option><option>10 bps · 压力</option></UiSelect></label></template><UiButton block @click="fresh">开始合约盲测</UiButton><button v-if="!before" type="button" class="proto-cost-toggle" :aria-expanded="costOpen" @click="costOpen=!costOpen">资金与成本 <span>10,000 USDT · 5×</span><Settings2 :size="14" /></button><div v-if="!before" class="proto-start-meta"><span>当前：{{ dataPool }}</span><button type="button" @click="dataOpen=true">数据与训练规则 ↗</button></div><p v-else class="proto-caption">固定费率 / 数据版本 / 未见场景数量 / 准入说明……</p></section>
      </div>
    </template>
    <template v-else-if="sceneNow==='records'">
      <div class="proto-record-heading"><div><span class="proto-eyebrow">TRACK / REVIEW</span><h2>交易追踪</h2></div><span class="proto-chip">演示记录</span></div>
      <div class="proto-line-tabs proto-record-tabs"><button type="button" @click="notice='本原型聚焦演练记录；实盘与模拟的原入口保留。'">实盘与模拟</button><button type="button" aria-pressed="true">{{ before ? '历史演练' : '演练记录' }}</button><button type="button" @click="notice='战法库入口保留；本轮不调整其内容。'">战法库</button></div>
