      <div class="proto-record-table"><div class="proto-record-row proto-table-head"><span>市场 / 标的</span><span>练习状态</span><span>结果</span><span>操作</span></div><div v-for="r in before ? filtered.filter(v=>v.market==='A股') : filtered" :key="r.id" class="proto-record-row"><div><span class="proto-chip">{{ r.market }}</span><strong>{{ r.symbol }}</strong><small>{{ r.kind }} · {{ r.id }} · {{ r.date }}</small></div><div><strong>{{ r.status }}</strong><small>{{ r.progress }}</small></div><span :class="{'proto-positive':r.result.startsWith('+')}">{{ r.result }}</span><div><UiButton variant="secondary" @click="resume(r)">{{ r.status==='进行中'?'继续练习':'查看复盘' }}</UiButton><button type="button" class="proto-text-button" @click="selectedRecord=r;detailOpen=true">详情</button></div></div><div v-if="!filtered.length" class="proto-empty">没有符合筛选条件的演练。<button type="button" @click="market='全部';status='全部状态';attempt='全部类型';keyword=''">重置筛选</button></div></div>
