      <section v-else-if="!revealed" class="proto-review-card"><Check :size="22" /><h3>首次盲评已保留</h3><div class="proto-skeleton"></div><div class="proto-skeleton short"></div><UiButton @click="revealed=true">揭晓完整行情</UiButton></section>
      <template v-else><div class="proto-review-metrics"><div v-for="label in ['收益率','最大回撤','手续费 / 资金费']" :key="label"><span>{{ label }}</span><strong>—</strong></div></div><section class="proto-review-card"><h3>入场计划与实际退出</h3><div v-for="n in 3" :key="n" class="proto-skeleton"></div><label>下次只改哪一件事？<textarea aria-label="原型事后复盘" placeholder="留下一个具体调整"></textarea></label><UiButton v-if="!reviewSaved" @click="reviewAction">保存复盘到演练记录</UiButton><UiButton v-else variant="secondary" @click="fresh();notice='已建立新的演示复练，原首次记录保留。'">按原版本复练</UiButton></section><details class="proto-review-card"><summary>操作轨迹、资金账本与冻结规则</summary><div v-for="n in 5" :key="n" class="proto-skeleton"></div></details></template>
    </template>
