      <div v-if="before" class="proto-rule-block"><strong>保守教学结算</strong><p>触发接管后全仓关闭，该仓保证金不返还；固定训练费率，分钟撮合与容量为教学近似……</p></div>
      <div class="proto-account-strip" data-feature="precision"><div v-for="(label,i) in ['账户权益','可用保证金','委托冻结','本次净盈亏']" :key="label"><span>{{ label }}</span><strong>{{ before ? (i<2?'10,000.00000000':'0.00000000') : (i<2?'10,000.00':'0.00') }}<small v-if="!before && i===0"> USDT</small></strong></div></div>
      <div v-if="before" class="proto-progress">第1天 00:45 · 已展示 {{ clock }} / 4321 分钟 <span>━━━━</span> 5倍 · 首次练习</div>
      <div class="proto-trading-layout">
        <aside v-if="variant==='B'" class="proto-focus-rail"><button type="button" class="proto-icon" title="下单面板" aria-label="展开专注模式下单" @click="orderOpen=!orderOpen"><PanelRightOpen :size="17" /></button><button type="button" class="proto-icon" title="数据与规则" aria-label="专注模式数据" @click="dataOpen=true"><Database :size="17" /></button><button type="button" class="proto-icon" title="演练记录" aria-label="专注模式记录" @click="toScene('records')"><Clock3 :size="17" /></button></aside>
        <div class="proto-chart-and-position">
          <section class="proto-chart-area" data-feature="layout">
            <header class="proto-chart-toolbar"><strong v-if="before">观察行情</strong><div class="proto-period-buttons"><button v-for="p in ['5m','15m','1h','4h']" :key="p" type="button" :aria-pressed="periods[selected]===p" @click="changePeriod(p)">{{ p }}</button></div><UiSelect :model-value="periods[selected]" aria-label="选中图周期" @update:model-value="changePeriod"><option v-for="p in ['1m','5m','15m','1h','4h','1D']" :key="p">{{ p }}</option></UiSelect><UiSelect v-model="sources[selected]" aria-label="选中图价格类型"><option>最新价</option><option>标记价格</option></UiSelect><template v-if="!before"><button type="button" class="proto-icon" title="图表布局与联动" aria-label="图表布局与联动" :aria-expanded="layoutOpen" @click="layoutOpen=!layoutOpen"><Grid2X2 :size="16" /></button><button type="button" class="proto-icon" title="放大选中图 / 恢复布局" aria-label="放大选中图" @click="maximized=maximized==null?selected:null"><Maximize2 :size="15" /></button><button v-if="variant==='A'" type="button" class="proto-icon" title="收起或展开下单面板" aria-label="收起或展开下单面板" @click="orderOpen=!orderOpen"><PanelRightClose v-if="!orderOpen" :size="16" /><PanelRightOpen v-else :size="16" /></button></template></header>
            <p v-if="before" class="proto-old-chart-copy">90天背景，72小时练习。仅聚合已知分钟；形成中K线只含已知部分。图表显示最近600根，切换日线可观察完整背景……</p>
            <div v-if="layoutOpen && !before" class="proto-layout-popover"><div class="proto-section-title"><strong>图表布局与联动</strong><button type="button" aria-label="收起布局设置" @click="layoutOpen=false">×</button></div><div class="proto-layout-options"><button v-for="[key,label] in [['single','单图'],['dual','双列'],['rows','双行'],['quad','四图']]" :key="key" type="button" :aria-pressed="layout===key" @click="layout=key;maximized=null;selected=0"><span :class="`layout-icon ${key}`"><i v-for="n in (key==='quad'?4:key==='single'?1:2)" :key="n"></i></span>{{ label }}</button></div><div class="proto-sync-options"><label><input v-model="crossSync" type="checkbox"> 十字线时间</label><label><input v-model="priceSync" type="checkbox"> 同价格水平线</label><label><input v-model="timeSync" type="checkbox"> 时间位置 / 拖动</label><label><input v-model="dateSync" type="checkbox"> 日期范围（含缩放）</label><label><input v-model="periodSync" type="checkbox" @change="periodSync && changePeriod(periods[selected])"> 周期（默认独立）</label></div><p>本局品种固定。价格线仅在相同价格类型之间同步；时间按实际分钟定位。</p></div>
            <div class="proto-chart-grid" :class="[before?'single':maximized!=null?'single':layout]" @pointerleave="crosshair=null"><PrototypeChart v-for="i in before?[0]:visibleCharts" :key="i" :index="i" :period="periods[i]" :symbol="instrument.replace(' 永续','')" :span-minutes="dateSync ? ({'1m':1,'5m':5,'15m':15,'1h':60,'4h':240,'1D':1440}[periods[selected]] * 44 / zoom) : 0" :source="sources[i]" :clock="clock" :offset="offsets[i]" :zoom="zoom" :crosshair="sources[i]===sources[crosshair?.index ?? i] ? crosshair : (crosshair ? {...crosshair,y:null} : null)" :linked="crossSync" :price-linked="priceSync && sources[i]===sources[crosshair?.index ?? i]" :active="selected===i" @activate="selected=i" @crosshair="crosshair=$event" @pan="selected=i;pan($event)" /></div>
            <div v-if="!before" class="proto-chart-view-controls"><span><Crosshair :size="12" /> 图{{ selected+1 }} · {{ periods[selected] }}</span><button type="button" @click="pan(30)">← 查看更早</button><button type="button" @click="pan(-30)">更近 →</button><button type="button" @click="offsets=[0,0,0,0]">回到当前</button><label>缩放<input v-model.number="zoom" aria-label="图表缩放" type="range" min="1" max="3" step=".5"></label></div>
            <div class="proto-playbar" data-feature="playback"><button v-if="!before" type="button" class="proto-icon" :aria-label="playing?'暂停演示回放':'演示自动回放'" @click="playing=!playing"><Pause v-if="playing" :size="14" /><Play v-else :size="14" /></button><span v-if="!before"><i class="proto-status-dot"></i>T+{{ clock }}m <small>/ 72h</small></span><button v-for="n in [1,5,15]" :key="n" type="button" :disabled="phase!=='active'" @click="advance(n)">{{ before?'推进 ': '+' }}{{ n }} 分钟</button><button type="button" class="proto-end" @click="finishOpen=true">{{ before?'结束并退出':'结束练习' }}</button></div>
          </section>
          <section v-if="!before" class="proto-position-panel" data-feature="position"><div class="proto-position-tabs"><button v-for="t in ['持仓','当前委托','历史委托','成交']" :key="t" type="button" :aria-pressed="tab===t" @click="tab=t">{{ t }} <small>{{ orderCount(t) }}</small></button><button type="button" class="proto-text-button proto-to-records" @click="toScene('records')">演练记录 ↗</button></div><template v-if="tab==='持仓'"><div class="proto-position-summary"><div><span>当前持仓</span><strong>{{ held?'BTCUSDT · 多':'空仓' }}</strong></div><div><span>浮动盈亏</span><strong>{{ held?'+12.40':'—' }}</strong></div><div><span>逐仓保证金</span><strong>{{ held?margin.toFixed(2):'—' }}</strong></div><div><span>估算强平价 · mark</span><strong>{{ held?'67,800.0':'—' }}</strong></div></div><div class="proto-position-actions"><span class="proto-chip">{{ protection?'自动止损已设置':manualPlan?'仅手动计划 · 不自动执行':'未设退出价' }}</span><button type="button" @click="held=true;notice='已装载示例持仓，便于检查平仓、止损与保证金入口。'">装载示例持仓</button><button type="button" @click="planOpen=true">{{ held?'止盈止损 / 手动计划':'设置退出计划' }}</button><button type="button" :disabled="!held" @click="margin+=100;notice='演示追加100 USDT，仍承担本仓风险；仓外资金不自动补入。'">调整保证金 +100</button><button type="button" :disabled="!held" @click="held=false;notice='已模拟平仓；本局仍可继续观察。'">市价平仓</button><button type="button" @click="detailOpen=true;selectedRecord=records[0]">完整精度与详情</button></div></template><div v-else-if="displayedOrders.length" class="proto-orders-list"><div v-for="(o,i) in displayedOrders" :key="i"><span>{{ o.side }} · {{ o.type }} · {{ o.quantity }} {{ o.unit }}</span><button v-if="tab==='当前委托'" type="button" @click="cancel(o)">撤单</button><span v-else>{{ o.status==='canceled'?'已撤销':'已成交' }}</span></div></div><div v-else class="proto-empty">暂无{{ tab }}。可在下单区提交一笔演示委托。</div><p v-if="held" class="proto-context">教学强平：达到阈值可能全仓接管；估算强平价不保证成交。</p></section>
          <section v-else class="proto-before-review"><span class="proto-eyebrow">记录判断，再揭晓</span><h3>这次练习，留下什么？</h3><div class="proto-rule-block">保守教学结算 / 模型差异说明……</div><div v-for="n in 5" :key="n" class="proto-skeleton"></div><details open><summary>执行与风险事件（12）</summary><div v-for="n in 4" :key="n" class="proto-event-skeleton"><i></i><div class="proto-skeleton"></div></div></details><details><summary>资金账本</summary><div class="proto-skeleton"></div></details></section>
        </div>
        <aside v-if="before" class="proto-before-aside"><section><h3>持仓与退出</h3><span class="proto-chip">未设退出价</span><div v-for="label in ['当前持仓','对应币数','名义仓位','入场均价','逐仓保证金','mark 浮动盈亏','浮盈亏 / 权益','标记价格','风险率','估算强平价','距强平价','计划退出价','计划盈亏估算']" :key="label" class="proto-old-fact"><span>{{ label }}</span><b>—</b></div><p class="proto-caption">计划估算未含手续费、资金费、滑点……</p><div class="proto-rule-block">追加保证金与强平模型说明……</div></section><section><h3>手动退出计划</h3><label>计划方式<UiSelect aria-label="原布局计划方式"><option>未设退出价</option><option>手动退出</option></UiSelect></label><label>原因<UiInput placeholder="记录计划原因" /></label><UiButton variant="secondary" @click="notice='原布局：手动计划位于下单上方。'">保存退出计划</UiButton></section><PrototypeOrder before @submit="submit" @state="orderDraft=$event" /></aside>
        <aside v-else-if="variant==='A'&&!orderOpen || variant==='C'" class="proto-order-aside"><PrototypeOrder :disabled="phase!=='active'" @submit="submit" @state="orderDraft=$event" /><p class="proto-risk-summary"><Info :size="13" />{{ held?'当前有持仓 · 留意退出与强平风险':'当前空仓 · 可以先观察' }}<button type="button" @click="planOpen=true">退出计划</button></p></aside>
      </div>
      <div v-if="!before" class="proto-session-footer"><span>进度自动保存 · 保留首次判断</span><button type="button" @click="dataOpen=true;dataTab='训练规则'">教学模型与实盘差异</button><button v-if="variant==='B'" type="button" @click="orderOpen=true">展开下单面板 →</button></div>
    </template>
    <UiDrawer :open="dataOpen" title="行情数据" description="数据池、来源和训练规则集中在这里。" :panel-class="drawerClass" @close="dataOpen=false"><div class="proto-line-tabs"><button v-for="t in ['数据池','数据来源','训练规则']" :key="t" type="button" :aria-pressed="dataTab===t" @click="dataTab=t">{{ t }}</button></div><template v-if="dataTab==='数据池'"><label>当前数据池<UiSelect v-model="dataPool" aria-label="演示数据池" :disabled="sceneNow!=='setup'"><option>OKX 历史池</option><option>未来数据池 · 占位演示</option></UiSelect></label><p class="proto-context">只在开局前选择；进行中的练习沿用原冻结版本。</p><div class="proto-data-metrics"><div><span>数据覆盖</span><strong>2024—2025</strong></div><div><span>可练场景</span><strong>210 <small>示例</small></strong></div></div><h4>覆盖与可用性</h4><div v-for="label in ['BTCUSDT · 普通价格 / 标记价格','ETHUSDT · 普通价格 / 标记价格','资金费归档 / 已准入窗口']" :key="label" class="proto-data-row"><span>{{ label }}</span><span class="proto-positive">已核验</span></div><p>覆盖明细、缺口和版本使用骨架展示。</p><div v-for="n in 3" :key="n" class="proto-skeleton"></div></template><template v-else-if="dataTab==='数据来源'"><h4>数据来源与处理</h4><div v-for="label in ['交易所历史行情归档','普通价格 / 标记价格 / 资金费','清洗、缺口和准入','冻结版本与更新时间']" :key="label" class="proto-data-row"><strong>{{ label }}</strong><div class="proto-skeleton short"></div></div><p>这里只展示池的总体覆盖，不揭露本局隐藏日期和未来行情。</p></template><template v-else><h4>训练近似与实盘差异</h4><details v-for="label in ['撮合：分钟数据、滑点与成交容量','强平：教学接管与保证金损失','资金费：结算采样与代理价格','恢复与复练：冻结版本与首次记录']" :key="label" open><summary>{{ label }}</summary><p>完整说明集中收纳；与当前动作有关的提示仍留在操作旁。</p><div class="proto-skeleton"></div></details></template></UiDrawer>
    <UiDrawer :open="settingsOpen" title="交易与显示设置" description="保留熟悉的设置名称，按用途分组。" :panel-class="drawerClass" @close="settingsOpen=false"><h4>交易偏好</h4><label>默认数量单位<UiSelect v-model="preferredUnit" aria-label="默认数量单位"><option>USDT</option><option>BTC</option><option>张</option></UiSelect></label><label class="proto-check"><input v-model="confirmClose" type="checkbox"> 平仓前确认</label><label class="proto-check"><input v-model="pauseOnEvent" type="checkbox"> 成交与风险事件后暂停</label><h4>显示</h4><label>价格显示精度<UiSelect v-model="precision" aria-label="价格显示精度"><option>自动 · 按标的</option><option>完整精度</option></UiSelect></label><p class="proto-context">主题使用原型顶部的深浅切换；布局、周期、面板宽度属于显示偏好。</p></UiDrawer>
    <UiDrawer :open="orderOpen && variant==='B'" title="下单" description="专注方案：图表保持全宽，需要时展开交易操作。" :panel-class="drawerClass" @close="orderOpen=false"><PrototypeOrder :disabled="phase!=='active'" @submit="submit" @state="orderDraft=$event" /></UiDrawer>
    <UiDrawer :open="planOpen" title="持仓与退出计划" description="手动计划是记录；自动止盈止损是保护委托。" :panel-class="drawerClass" @close="planOpen=false"><span class="proto-chip">{{ manualPlan?'手动计划已保存':'未设手动退出价' }}</span><h4>手动退出计划</h4><label>计划退出价<UiInput v-model="planPrice" aria-label="手动计划退出价" placeholder="输入计划价格" /></label><label>计划原因<UiInput aria-label="手动退出原因" placeholder="用一句话记录" /></label><UiButton variant="secondary" @click="manualPlan=true;notice='手动计划已保存，不会自动平仓。'">保存手动计划</UiButton><p class="proto-context">仅作训练记录，不会自动触发平仓。</p><h4>自动止盈止损</h4><label>自动止损价<UiInput aria-label="持仓自动止损价" placeholder="输入触发价格" /></label><label>触发依据<UiSelect><option>标记价格</option><option>最新价</option></UiSelect></label><UiButton @click="protection=true;notice='已设置演示保护委托。'">设置自动保护</UiButton><p class="proto-context">触发价不保证成交；图表价格切换不会改变委托依据。</p></UiDrawer>
    <UiDrawer :open="historyOpen" title="恢复历史练习 · 当前入口" description="选择一局即可继续，或查看已结束的练习。" :panel-class="drawerClass" @close="historyOpen=false"><button v-for="r in records.filter(v=>v.market==='加密合约')" :key="r.id" type="button" class="proto-history-item" @click="resume(r)">{{ r.symbol }} · {{ r.kind }} · {{ r.status }}</button></UiDrawer>
    <UiDrawer :open="detailOpen" :title="`${selectedRecord?.symbol ?? '本局'} · 演练详情`" description="按市场展示专属口径，保留完整精度供核对。" :panel-class="drawerClass" @close="detailOpen=false"><div class="proto-detail-facts"><span>记录 {{ selectedRecord?.id }}</span><span>市场 {{ selectedRecord?.market }}</span><span>账户权益 <b>10000.00000000 USDT</b></span></div><details v-for="label in selectedRecord?.market==='A股'?['逐笔成交','交易规则与费用','盲评与事后复盘']:['操作理由与退出计划','成交与风险事件','资金费与教学强平','资金账本','首次与复练比较','冻结规则与完整差异']" :key="label" open><summary>{{ label }}</summary><div class="proto-skeleton"></div><div class="proto-skeleton short"></div></details><UiButton variant="secondary" @click="resume(selectedRecord)">{{ selectedRecord?.status==='进行中'?'继续本局练习':'查看复盘流程' }}</UiButton></UiDrawer>
    <UiDrawer :open="finishOpen" title="结束本次练习？" description="结束练习会处理剩余持仓，之后先提交盲评，再揭晓。" :panel-class="drawerClass" @close="finishOpen=false"><p>“市价平仓”只处理仓位；“结束练习”结束这一局训练。</p><p v-if="held" class="proto-context">当前有示例持仓，结束时模拟退出。</p><UiButton @click="finish">结束并进入盲评</UiButton><UiButton variant="secondary" @click="finishOpen=false">继续观察</UiButton></UiDrawer>
  </div>
</template>
